import Header from "@/components/Header"; import Footer from "@/components/Footer"; import Hero from "@/components/Hero"; import {img} from "@/components/siteData";
export default function About(){return <><Header/><Hero eyebrow="ABOUT US" title="A FILIPINO COMPANY." highlight="A STRONGER TOMORROW." description="We manufacture high-quality piping and water storage solutions for a more sustainable Philippines." image={img.office}/><section className="about-story"><div className="about-intro"><small>OUR STORY</small><h2>Built on Purpose</h2><p>Central Negros Fujipipes Industries, Inc. (FUJIPIPES) is a proud Filipino manufacturing company located in the Negros Island Region.</p><p>We specialize in the production of high-quality HDPE, uPVC, PPR and other piping systems, plastic tanks, and related products that support communities across the Philippines.</p><p>Guided by quality, innovation and sustainability, we provide reliable solutions for infrastructure, agriculture, industrial and residential needs.</p><a href="/contact" className="blue-button">Learn More About Us →</a></div><div className="about-columns"><Info icon="🎯" title="Our Mission" text="To provide high-quality, innovative and sustainable piping and water storage solutions that enhance communities and contribute to a better Philippines."/><Info icon="◎" title="Our Vision" text="To be the most trusted and preferred Filipino manufacturer of piping and water storage solutions in the Philippines and beyond."/><Info icon="👥" title="Our Core Values" text="Quality, Integrity, Innovation, Sustainability and Customer Commitment."/></div></section><section className="about-features"><Feature icon="🏭" title="Local Manufacturing" text="Proudly made in the Philippines"/><Feature icon="👥" title="Trusted by Industries" text="Across the country"/><Feature icon="⚙" title="Wide Product Range" text="For diverse applications"/><Feature icon="🍃" title="A More Sustainable Tomorrow" text="For future generations"/></section><section className="manufacturing"><img src={img.factory} alt="Manufacturing"/><div><small>OUR MANUFACTURING</small><h2>Quality Through Innovation</h2><p>Our modern manufacturing facilities and strict quality control processes ensure that every Fujipipes product meets industry standards and customer requirements.</p><a href="/contact" className="outline-blue-button">Our Facilities →</a></div><img src={img.hdpe} alt="Fujipipes products"/></section><Footer/></>}
function Info({icon,title,text}:{icon:string;title:string;text:string}){return <div className="info-block"><div className="round-icon">{icon}</div><h3>{title}</h3><p>{text}</p></div>}
function Feature({icon,title,text}:{icon:string;title:string;text:string}){return <div className="about-feature"><span>{icon}</span><div><strong>{title}</strong><small>{text}</small></div></div>}
